#!/usr/bin/env python3
"""Provenance of the Unitree G1 body (bodies/unitree_g1/): MuJoCo Menagerie's unitree_g1/g1.xml (the 29-DOF G1 rev 1.0
of Unitree's g1_description, BSD-3-Clause) -> model.xml (the template body.py reads), meshes_fine/ (the Menagerie
meshes, unchanged) and meshes/ (decimated copies for the simulation, the players' cameras and in-task videos).

    python -I tools/make_model.py MENAGERIE_G1_DIR MENAGERIE_COMMIT       (needs mujoco, numpy, trimesh,
                                                                        fast-simplification; not in the image)

Changes against the Menagerie model (also listed in body.toml and the design note):
  actuators  the Menagerie position servos (kp 500, "needs tuning") are dropped; body.py adds one torque motor per
             joint at Unitree's URDF effort limits; the legs get torques from the walking policy's PD (or the kick
             controller), the waist and the arms from the body's servo;
  collision  the collision meshes become robot geoms (contype 4, conaffinity 0: they touch the ball, a table, a net,
             never the robot itself); the four foot spheres stay as they are (the floor contacts the walking policy was
             validated with, sim-to-sim in MuJoCo by Unitree); one box under each foot (contype 8) touches only a ball
             that carries conaffinity bit 8 (a soccer ball): the instep and toe for kicking;
  mounts     a wrist mount on each hand (body <side>_mount at the rubber hand, +z along the forearm) and a stereo head
             camera (two cameras 5 cm apart, 58 degree vertical field of view: the G1 head's Intel RealSense D435i
             class depth camera; its tilt is a mount parameter); light, sensors and keyframe dropped.
"""
from __future__ import annotations

import shutil
import sys
import xml.etree.ElementTree as ET
from pathlib import Path

import numpy as np

HERE = Path(__file__).resolve().parents[1]
DECIMATE = 0.15


def decimate(src: Path, dst: Path):
    import fast_simplification
    import trimesh
    m = trimesh.load(src, force="mesh", process=True)
    target = max(300, int(len(m.faces) * DECIMATE))
    if len(m.faces) > target:
        v2, f2 = fast_simplification.simplify(np.asarray(m.vertices, np.float32), np.asarray(m.faces, np.int32),
                                              target_reduction=1.0 - target / len(m.faces))
        m = trimesh.Trimesh(v2, f2, process=True)
    dst.parent.mkdir(parents=True, exist_ok=True)
    m.export(dst)
    return len(m.faces)


def main(src_dir: str, commit: str):
    src_dir = Path(src_dir)
    root = ET.parse(src_dir / "g1.xml").getroot()
    fine, coarse = HERE / "meshes_fine", HERE / "meshes"
    for d in (fine, coarse):
        if d.exists():
            shutil.rmtree(d)
        d.mkdir()
    asset = root.find("asset")
    nf = 0
    for m in asset.findall("mesh"):
        f = m.get("file")
        if m.get("name") is None:
            m.set("name", Path(f).stem)
        shutil.copy2(src_dir / "assets" / f, fine / f)
        nf += decimate(src_dir / "assets" / f, coarse / (Path(f).stem + ".stl"))
        m.set("file", Path(f).stem + ".stl")
        m.set("name", "g1_" + m.get("name"))
    shutil.copy2(src_dir / "LICENSE", HERE / "LICENSE")
    for mat in asset.findall("material"):
        mat.set("name", "g1_m_" + mat.get("name"))
    for tag in ("actuator", "sensor", "keyframe", "option"):
        for el in root.findall(tag):
            root.remove(el)
    root.set("model", "unitree_g1")
    root.find("compiler").set("meshdir", "meshes")
    root.find("compiler").set("autolimits", "true")
    root.insert(0, ET.Comment(
        f" Generated by bodies/unitree_g1/tools/make_model.py from MuJoCo Menagerie unitree_g1/g1.xml (commit {commit}, "
        "BSD-3-Clause, LICENSE; derived from Unitree's g1_description g1_29dof_rev_1_0). Template of the RoboOlympics "
        "Unitree G1 body: read by body.py, which prefixes every name, picks the mesh level and mounts the hand and the "
        "motors. Do not edit. "))
    # defaults: rename the classes, robot collision bits
    for el in root.iter():
        for a in ("class", "childclass"):
            if el.get(a):
                el.set(a, "g1_" + el.get(a))
        if el.tag == "geom" and el.get("material"):
            el.set("material", "g1_m_" + el.get("material"))
        if el.tag == "geom" and el.get("mesh"):
            el.set("mesh", "g1_" + el.get("mesh"))
    for d in root.find("default").iter("default"):
        if d.get("class") == "g1_collision":
            g = d.find("geom")
            g.set("contype", "4")
            g.set("conaffinity", "0")
        if d.get("class") == "g1_foot":
            g = d.find("geom")
            g.set("contype", "1")
            g.set("conaffinity", "1")
    wb = root.find("worldbody")
    for el in list(wb):
        if el.tag == "light":
            wb.remove(el)
    bodies = {b.get("name"): b for b in root.iter("body")}
    for side in ("left", "right"):
        foot = bodies[f"{side}_ankle_roll_link"]
        ET.SubElement(foot, "geom", name=f"{side}_foot_strike", type="box", pos="0.035 0 -0.02",
                      size="0.105 0.04 0.022", contype="8", conaffinity="0", group="3", mass="0", density="0",
                      rgba="0.2 0.6 0.9 0.3")
        hand = bodies[f"{side}_wrist_yaw_link"]
        sgn = 1.0 if side == "left" else -1.0
        ET.SubElement(hand, "body", name=f"{side}_mount", pos=f"0.08 {0.003 * sgn:.4f} 0",
                      quat="0.7071068 0 0.7071068 0")
    torso = bodies["torso_link"]
    # the head (head_link mesh in the torso frame): the camera pair in front of the face, looking along +x; the tilt
    # is set by body.py (head_pitch); MuJoCo cameras look along their local -z (xyaxes: x right, y up)
    head = ET.SubElement(torso, "body", name="head_cam", pos="0.08 0 0.39")
    for cam, y in (("head_left", 0.025), ("head_right", -0.025)):
        ET.SubElement(head, "camera", name=cam, pos=f"0 {y} 0", xyaxes="0 -1 0 0 0 1", fovy="58")
    ET.SubElement(head, "site", name="head_center", size="0.01", group="5")
    ET.indent(root, space="  ")
    (HERE / "model.xml").write_text(ET.tostring(root, encoding="unicode") + "\n")
    print("faces (meshes/):", nf)


if __name__ == "__main__":
    main(*sys.argv[1:3])
